    yieldInfoStep4Desc: 'Enter your total farming area in hectares. 1 hectare = 2.47 acres = 4 bigha (approx). This directly multiplies with per-hectare yield to give total production.',
    yieldInfoStep5Title: '🌧️ Step 5: Annual Rainfall (mm)',
    yieldInfoStep5Desc: 'Enter expected annual rainfall in millimeters. India averages 1180mm/year. Higher rainfall generally benefits water-intensive crops like Rice, while moderate rainfall suits Wheat.',
    yieldInfoStep6Title: '🧪 Step 6: Fertilizer Used (kg)',
    yieldInfoStep6Desc: 'Enter total fertilizer applied in kilograms. This includes Urea, DAP, NPK, and other fertilizers combined. More fertilizer does not always mean more yield — the AI finds the optimal balance.',
    yieldInfoResultTitle: '📊 Understanding Your Results',
    yieldInfoResultDesc: 'The result shows: Total Yield (tons) — your estimated total harvest, Per Hectare Yield — production efficiency, and Estimated Market Value — calculated at average market rates.',
    yieldGuideTitle: '📖 Quick Guide: How to Predict Your Harvest',
    yieldGuideText: '1️⃣ Enter your crop name (e.g., Rice, Wheat)\n2️⃣ Select the farming season\n3️⃣ Choose your state for regional accuracy\n4️⃣ Enter farm area in hectares\n5️⃣ Add annual rainfall & fertilizer amount\n6️⃣ Click Predict Yield to see your estimated harvest!',
    yieldProTip: '💡 Pro Tip: Try different crop + season combinations to find the most profitable option for your region.',
    fertInfoTitle: '📖 How to Use the Fertilizer Guide',
    fertInfoIntro: 'This tool acts as a Soil Doctor — it analyzes your soil nutrient levels, climate conditions, and crop type to prescribe the exact fertilizer your farm needs. Think of it as a medical prescription for your soil!',
    fertInfoStep1Title: '🧪 Step 1: Enter Soil Nutrients (N-P-K)',
    fertInfoStep1Desc: 'Enter your soil\'s current Nitrogen (N), Phosphorus (P), and Potassium (K) levels in mg/kg. You can get these values from a soil test report from your local Krishi Vigyan Kendra (KVK) or agricultural lab. If you don\'t know, start with low values (N:30, P:10, K:10) to see what\'s recommended.',
    fertInfoStep2Title: '🌡️ Step 2: Climate Conditions',
    fertInfoStep2Desc: 'Enter current temperature (°C) and humidity (%). These affect how fertilizers dissolve and are absorbed by plants. Higher humidity means slower fertilizer absorption; very hot temperatures can burn crop roots if fertilizer is applied midday.',
    fertInfoStep3Title: '🏜️ Step 3: Select Soil Type',
    fertInfoStep3Desc: 'Choose your soil type: Sandy (light, drains fast, needs more fertilizer), Loamy (ideal, holds nutrients well), Black/Cotton soil (heavy, retains water), Red (acidic, iron-rich), or Clayey (heavy, poor drainage). Each soil responds differently to fertilizers.',
    fertInfoStep4Title: '🌱 Step 4: Select Crop Type',
    fertInfoStep4Desc: 'Choose what you\'re growing. Each crop has unique nutrient needs — Rice needs high Nitrogen, Pulses fix their own Nitrogen, Cotton needs balanced NPK. The AI customizes the prescription based on your specific crop.',
    fertInfoResultTitle: '📋 Understanding Your Prescription',
    fertInfoResultDesc: 'Your result shows: Recommended Fertilizer (name + type), how to apply it, detected nutrient deficiencies (⚠️ Nitrogen/Phosphorus/Potassium), and dosage guidance. The common fertilizer reference below explains each fertilizer type.',
    fertInfoNPKTitle: '🔬 What is N-P-K?',
    fertInfoNPKDesc: 'N (Nitrogen) — promotes leaf growth and green color. Low N = yellow leaves, stunted growth.\nP (Phosphorus) — helps root growth, flowering, and fruit. Low P = weak roots, delayed fruiting.\nK (Potassium) — strengthens disease resistance and water regulation. Low K = brown leaf edges, weak stems.',
    fertInfoWhenTitle: '⏰ When to Test Your Soil?',
    fertInfoWhenDesc: 'Test before each season (Kharif: April-May, Rabi: September-October). Collect soil from 6-8 spots in your field at 6-inch depth, mix them, and send 500g to your nearest KVK or agricultural university lab.',
    fertGuideTitle: '📖 Quick Guide: Get Your Fertilizer Prescription',
    fertGuideText: '1️⃣ Enter current N, P, K values from your soil test\n2️⃣ Add temperature & humidity\n3️⃣ Select your soil type\n4️⃣ Choose what crop you\'re growing\n5️⃣ Click Get Prescription for AI-recommended fertilizer!\n\n⚠️ Don\'t have a soil test? Use low default values — the AI will recommend a general-purpose fertilizer.',
    fertProTip: '💡 Pro Tip: Apply fertilizer in split doses (at sowing + 30 days later) instead of all at once. This improves absorption and avoids burning roots.',
    weatherInfoDetailed: 'This module has two powerful features:\n\n🌍 Live Weather (Automatic): Fetches real-time weather using your device\'s GPS location. Shows current temperature, humidity, wind speed, pressure, and visibility. Provides farming-specific advisory — when to irrigate, risk of pests, and safe spraying windows.\n\n📊 Risk Analysis (Manual): Select any month and temperature to predict flood, drought, or normal conditions. The AI uses historical weather patterns trained on decades of Indian meteorological data. Great for planning which season to plant which crop.\n\n💡 Tip: Check weather before spraying pesticides — avoid spraying if rain is expected within 6 hours.',
    soilInfoDetailed: 'This tool gives you a comprehensive soil health report card:\n\n🟢 Nitrogen (N): The most important nutrient for crops. Controls leaf growth and plant vigor. Range: 0-140 mg/kg. Low N (<40) means your crops will be pale yellow and grow slowly.\n\n🟠 Phosphorus (P): Critical for root development and flowering. Range: 0-140 mg/kg. Low P (<25) leads to weak roots and poor fruit formation.\n\n🔵 Potassium (K): Strengthens the plant against disease and drought. Range: 0-200 mg/kg. Low K (<30) causes brown leaf edges and weak stems.\n\n📊 Your Report Includes:\n• Fertility Score — overall soil health rating (0-100)\n• Status — Fertile / Semi-Fertile / Infertile\n• Nutrient-by-nutrient analysis with optimal ranges\n• Specific fertilizer recommendations with dosage\n• Yield potential estimate based on soil quality\n• Precautions and actions for improvement\n\n💡 Tip: Use the sliders to test different N-P-K combinations and see how they affect your soil rating.',
    cropInfoDetailed: 'Our AI analyzes 7 key parameters to find the perfect crop for your conditions:\n\n🧪 1. Soil Nutrients (N-P-K): Different crops need different nutrient levels. Rice needs high N (80+), Pulses fix their own N, Cotton needs balanced NPK.\n\n🔬 2. Soil pH (0-14): Most crops prefer pH 6-7 (slightly acidic to neutral). Rice tolerates acidic soil (pH 5-6), while Wheat prefers neutral (pH 6.5-7.5).\n\n🌡️ 3. Temperature: Each crop has an optimal temperature range. Rice: 20-35°C, Wheat: 10-25°C, Cotton: 25-35°C. Outside this range, yield drops significantly.\n\n💧 4. Humidity: Affects pest pressure and disease. High humidity (>80%) favors Rice but increases fungal risk. Low humidity suits Millets and Pulses.\n\n🌧️ 5. Rainfall: Directly impacts water availability. Rice needs >200mm, Wheat needs 75-100mm, Cotton needs 50-100mm per month.\n\n📊 Our AI model is trained on lakhs of data points from Indian agricultural surveys. It shows the best crop match with a confidence score (%), ideal growing conditions, and season recommendation.\n\n💡 Tip: Try entering slightly different values to see which crops are recommended — this helps you find alternatives if your first choice doesn\'t work.',
    settingsSelected: 'Selected',

