    yieldInfoIntro: 'ఈ సాధనం ప్రభుత్వ వ్యవసాయ డేటాపై శిక్షణ పొందిన AI ఉపయోగిస్తుంది. మీ పంట రకం, స్థానం, భూమి విస్తీర్ణం, వర్షపాతం మరియు ఎరువు వాడకాన్ని విశ్లేషించి టన్నులలో మొత్తం దిగుబడిని అంచనా వేస్తుంది.',
