    yieldInfoStep6Title: '🧪 దశ 6: ఎరువులు (కిలోలు)',
    yieldInfoStep6Desc: 'కిలోగ్రాములలో మొత్తం ఎరువు నమోదు చేయండి. ఎక్కువ ఎరువు ఎల్లప్పుడూ ఎక్కువ దిగుబడి కాదు — AI సరైన సమతుల్యత కనుగొంటుంది.',
