    yieldGuideTitle: '📖 శీఘ్ర మార్గదర్శి: మీ పంట అంచనా ఎలా వేయాలి',
    yieldGuideText: '1️⃣ పంట పేరు నమోదు చేయండి\n2️⃣ సీజన్ ఎంచుకోండి\n3️⃣ రాష్ట్రం ఎంచుకోండి\n4️⃣ హెక్టార్లలో విస్తీర్ణం నమోదు చేయండి\n5️⃣ వర్షపాతం & ఎరువు మొత్తం జోడించండి\n6️⃣ దిగుబడి అంచనా క్లిక్ చేయండి!',
    yieldProTip: '💡 చిట్కా: మీ ప్రాంతానికి అత్యంత లాభదాయక ఎంపిక కనుగొనడానికి వివిధ పంట + సీజన్ కలయికలు ప్రయత్నించండి.',
    fertInfoTitle: '📖 ఎరువుల గైడ్ ఎలా ఉపయోగించాలి',
    fertInfoIntro: 'ఈ సాధనం నేల వైద్యుడు వలె పనిచేస్తుంది — మీ నేల పోషకాలు, వాతావరణం మరియు పంటను విశ్లేషించి సరైన ఎరువు ప్రిస్క్రిప్షన్ ఇస్తుంది.',
    fertInfoStep1Title: '🧪 దశ 1: నేల పోషకాలు (N-P-K)',
    fertInfoStep1Desc: 'మీ నేల నైట్రోజన్, ఫాస్పరస్, పొటాషియం స్థాయిలు mg/kg లో నమోదు చేయండి. ఈ విలువలు మీ స్థానిక కృషి విజ్ఞాన కేంద్రం (KVK) నేల పరీక్ష నివేదిక నుండి తెలుస్తాయి.',
    fertInfoStep2Title: '🌡️ దశ 2: వాతావరణ పరిస్థితులు',
    fertInfoStep2Desc: 'ప్రస్తుత ఉష్ణోగ్రత (°C) మరియు తేమ (%) నమోదు చేయండి.',
    fertInfoStep3Title: '🏜️ దశ 3: నేల రకం',
    fertInfoStep3Desc: 'ఇసుక (తేలికైన), లోమీ (ఆదర్శం), నల్ల (భారీ), ఎర్ర (ఆమ్లమైన), లేదా బంకమట్టి ఎంచుకోండి.',
    fertInfoStep4Title: '🌱 దశ 4: పంట రకం',
    fertInfoStep4Desc: 'మీరు ఏమి పండిస్తున్నారో ఎంచుకోండి. ప్రతి పంటకు ప్రత్యేక పోషక అవసరాలు ఉంటాయి.',
    fertInfoResultTitle: '📋 ప్రిస్క్రిప్షన్ అర్థం చేసుకోండి',
    fertInfoResultDesc: 'ఫలితం చూపిస్తుంది: సిఫార్సు ఎరువు, ఎలా వేయాలి, పోషక లోపాలు (⚠️ N/P/K), మరియు మోతాదు మార్గదర్శనం.',
    fertInfoNPKTitle: '🔬 N-P-K అంటే ఏమిటి?',
    fertInfoNPKDesc: 'N (నైట్రోజన్) — ఆకుల పెరుగుదల. తక్కువ N = పసుపు ఆకులు.\nP (ఫాస్పరస్) — వేరు అభివృద్ధి. తక్కువ P = బలహీన వేళ్ళు.\nK (పొటాషియం) — వ్యాధి నిరోధకత. తక్కువ K = గోధుమ ఆకుల అంచులు.',
    fertInfoWhenTitle: '⏰ నేలను ఎప్పుడు పరీక్షించాలి?',
    fertInfoWhenDesc: 'ప్రతి సీజన్ ముందు. మీ పొలంలో 6-8 చోట్ల నుండి 6 అంగుళాల లోతున మట్టి తీయండి, కలపండి, 500 గ్రాములు మీ సమీపంలోని KVK కి పంపండి.',
    fertGuideTitle: '📖 శీఘ్ర మార్గదర్శి: ఎరువు ప్రిస్క్రిప్షన్ పొందండి',
    fertGuideText: '1️⃣ నేల పరీక్ష నుండి N, P, K విలువలు నమోదు చేయండి\n2️⃣ ఉష్ణోగ్రత & తేమ జోడించండి\n3️⃣ నేల రకం ఎంచుకోండి\n4️⃣ పంట ఎంచుకోండి\n5️⃣ ప్రిస్క్రిప్షన్ పొందండి క్లిక్ చేయండి!\n\n⚠️ నేల పరీక్ష లేదా? తక్కువ విలువలు వాడండి — AI సాధారణ ఎరువు సిఫార్సు చేస్తుంది.',
    fertProTip: '💡 చిట్కా: ఎరువును ఒకేసారి కాకుండా విభజించి వేయండి (విత్తనం వేసేటప్పుడు + 30 రోజుల తర్వాత).',
    weatherInfoDetailed: 'ఈ మాడ్యూల్‌లో రెండు శక్తివంతమైన ఫీచర్లు ఉన్నాయి:\n\n🌍 లైవ్ వాతావరణం (ఆటోమేటిక్): మీ GPS స్థానం ఉపయోగించి నిజ-సమయ వాతావరణం — ఉష్ణోగ్రత, తేమ, గాలి వేగం.\n\n📊 ప్రమాద విశ్లేషణ (మాన్యువల్): ఏదైనా నెల & ఉష్ణోగ్రత ఎంచుకుని వరద, కరువు లేదా సాధారణ పరిస్థితుల అంచనా వేయండి.\n\n💡 చిట్కా: పురుగుమందు చల్లే ముందు వాతావరణం చూడండి.',
    soilInfoDetailed: 'ఈ సాధనం సమగ్ర మట్టి ఆరోగ్య రిపోర్ట్ కార్డ్ ఇస్తుంది:\n\n🟢 నైట్రోజన్ (N): అత్యంత ముఖ్యమైన పోషకం. పరిధి: 0-140 mg/kg.\n\n🟠 ఫాస్పరస్ (P): వేరు అభివృద్ధికి కీలకం. పరిధి: 0-140 mg/kg.\n\n🔵 పొటాషియం (K): వ్యాధి నిరోధకత. పరిధి: 0-200 mg/kg.\n\n📊 నివేదికలో:\n• సారవంత స్కోర్ (0-100)\n• పోషక విశ్లేషణ\n• ఎరువు సిఫార్సులు\n\n💡 చిట్కా: స్లైడర్లతో వివిధ N-P-K కలయికలు ప్రయత్నించండి.',
    cropInfoDetailed: 'మా AI 7 ముఖ్య కారకాలను విశ్లేషించి మీ పరిస్థితులకు సరైన పంటను కనుగొంటుంది:\n\n🧪 1. నేల పోషకాలు (N-P-K)\n🔬 2. నేల pH\n🌡️ 3. ఉష్ణోగ్రత\n💧 4. తేమ\n🌧️ 5. వర్షపాతం\n\n📊 AI మోడల్ లక్షల భారత కృషి సర్వే డేటాపై శిక్షణ పొందింది.\n\n💡 చిట్కా: విభిన్న విలువలు ప్రయత్నించి ప్రత్యామ్నాయ పంటలు కనుగొనండి.',
