    yieldGuideTitle: '📖 ತ್ವರಿತ ಮಾರ್ಗದರ್ಶಿ: ನಿಮ್ಮ ಫಸಲು ಅಂದಾಜು',
    yieldGuideText: '1️⃣ ಬೆಳೆ ಹೆಸರು ನಮೂದಿಸಿ\n2️⃣ ಋತು ಆಯ್ಕೆಮಾಡಿ\n3️⃣ ರಾಜ್ಯ ಆಯ್ಕೆಮಾಡಿ\n4️⃣ ಹೆಕ್ಟೇರ್‌ನಲ್ಲಿ ವಿಸ್ತೀರ್ಣ ನಮೂದಿಸಿ\n5️⃣ ಮಳೆ & ಗೊಬ್ಬರ ಪ್ರಮಾಣ ಸೇರಿಸಿ\n6️⃣ ಇಳುವರಿ ಅಂದಾಜು ಕ್ಲಿಕ್ ಮಾಡಿ!',
    yieldProTip: '💡 ಸಲಹೆ: ನಿಮ್ಮ ಪ್ರದೇಶಕ್ಕೆ ಅತ್ಯಂತ ಲಾಭದಾಯಕ ಆಯ್ಕೆ ಕಂಡುಹಿಡಿಯಲು ವಿವಿಧ ಬೆಳೆ + ಋತು ಸಂಯೋಜನೆಗಳನ್ನು ಪ್ರಯತ್ನಿಸಿ.',
    fertInfoTitle: '📖 ಗೊಬ್ಬರ ಮಾರ್ಗದರ್ಶಿ ಬಳಕೆ ವಿಧಾನ',
    fertInfoIntro: 'ಈ ಸಾಧನವು ಮಣ್ಣಿನ ವೈದ್ಯರ ಹಾಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ — ನಿಮ್ಮ ಮಣ್ಣಿನ ಪೋಷಕಾಂಶಗಳು, ಹವಾಮಾನ ಮತ್ತು ಬೆಳೆಯನ್ನು ವಿಶ್ಲೇಷಿಸಿ ಸರಿಯಾದ ಗೊಬ್ಬರ ಪ್ರಿಸ್ಕ್ರಿಪ್ಷನ್ ನೀಡುತ್ತದೆ.',
    fertInfoStep1Title: '🧪 ಹಂತ 1: ಮಣ್ಣಿನ ಪೋಷಕಾಂಶಗಳು (N-P-K)',
    fertInfoStep1Desc: 'ನಿಮ್ಮ ಮಣ್ಣಿನ ಸಾರಜನಕ, ರಂಜಕ, ಪೊಟ್ಯಾಷಿಯಂ ಮಟ್ಟಗಳನ್ನು mg/kg ನಲ್ಲಿ ನಮೂದಿಸಿ.',
    fertInfoStep2Title: '🌡️ ಹಂತ 2: ಹವಾಮಾನ ಪರಿಸ್ಥಿತಿಗಳು',
    fertInfoStep2Desc: 'ಪ್ರಸ್ತುತ ಉಷ್ಣತೆ (°C) ಮತ್ತು ಆರ್ದ್ರತೆ (%) ನಮೂದಿಸಿ.',
    fertInfoStep3Title: '🏜️ ಹಂತ 3: ಮಣ್ಣಿನ ಪ್ರಕಾರ',
    fertInfoStep3Desc: 'ಮರಳು (ಹಗುರ), ಕೆಸರು (ಉತ್ತಮ), ಕಪ್ಪು (ಭಾರಿ), ಕೆಂಪು (ಆಮ್ಲೀಯ), ಅಥವಾ ಜೇಡಿಮಣ್ಣು ಆಯ್ಕೆಮಾಡಿ.',
    fertInfoStep4Title: '🌱 ಹಂತ 4: ಬೆಳೆ ಪ್ರಕಾರ',
    fertInfoStep4Desc: 'ನೀವು ಏನು ಬೆಳೆಯುತ್ತಿದ್ದೀರಿ ಎಂದು ಆಯ್ಕೆಮಾಡಿ. ಪ್ರತಿ ಬೆಳೆಗೆ ವಿಶಿಷ್ಟ ಪೋಷಕ ಅಗತ್ಯಗಳಿವೆ.',
    fertInfoResultTitle: '📋 ಪ್ರಿಸ್ಕ್ರಿಪ್ಷನ್ ಅರ್ಥಮಾಡಿಕೊಳ್ಳಿ',
    fertInfoResultDesc: 'ಫಲಿತಾಂಶ ತೋರಿಸುತ್ತದೆ: ಶಿಫಾರಸು ಗೊಬ್ಬರ, ಹೇಗೆ ಹಾಕಬೇಕು, ಪೋಷಕ ಕೊರತೆಗಳು (⚠️ N/P/K).',
    fertInfoNPKTitle: '🔬 N-P-K ಎಂದರೇನು?',
    fertInfoNPKDesc: 'N (ಸಾರಜನಕ) — ಎಲೆ ಬೆಳವಣಿಗೆ. ಕಡಿಮೆ N = ಹಳದಿ ಎಲೆಗಳು.\nP (ರಂಜಕ) — ಬೇರು ಬೆಳವಣಿಗೆ. ಕಡಿಮೆ P = ದುರ್ಬಲ ಬೇರುಗಳು.\nK (ಪೊಟ್ಯಾಷಿಯಂ) — ರೋಗ ನಿರೋಧಕ. ಕಡಿಮೆ K = ಕಂದು ಎಲೆ ಅಂಚುಗಳು.',
    fertInfoWhenTitle: '⏰ ಮಣ್ಣನ್ನು ಯಾವಾಗ ಪರೀಕ್ಷಿಸಬೇಕು?',
    fertInfoWhenDesc: 'ಪ್ರತಿ ಋತುವಿಗೆ ಮುಂಚೆ. ನಿಮ್ಮ ಹೊಲದಲ್ಲಿ 6-8 ಸ್ಥಳಗಳಿಂದ 6 ಇಂಚು ಆಳದಲ್ಲಿ ಮಣ್ಣು ತೆಗೆದು, ಬೆರೆಸಿ, 500 ಗ್ರಾಂ ನಿಮ್ಮ ಹತ್ತಿರದ KVK ಗೆ ಕಳಿಸಿ.',
    fertGuideTitle: '📖 ತ್ವರಿತ ಮಾರ್ಗದರ್ಶಿ: ಗೊಬ್ಬರ ಪ್ರಿಸ್ಕ್ರಿಪ್ಷನ್ ಪಡೆಯಿರಿ',
    fertGuideText: '1️⃣ ಮಣ್ಣಿನ ಪರೀಕ್ಷೆಯಿಂದ N, P, K ಮೌಲ್ಯಗಳು ನಮೂದಿಸಿ\n2️⃣ ಉಷ್ಣತೆ & ಆರ್ದ್ರತೆ ಸೇರಿಸಿ\n3️⃣ ಮಣ್ಣಿನ ಪ್ರಕಾರ ಆಯ್ಕೆಮಾಡಿ\n4️⃣ ಬೆಳೆ ಆಯ್ಕೆಮಾಡಿ\n5️⃣ ಪ್ರಿಸ್ಕ್ರಿಪ್ಷನ್ ಪಡೆಯಿರಿ ಕ್ಲಿಕ್ ಮಾಡಿ!',
    fertProTip: '💡 ಸಲಹೆ: ಗೊಬ್ಬರವನ್ನು ಒಮ್ಮೆಲೇ ಹಾಕಬೇಡಿ. ವಿಭಜಿಸಿ ಹಾಕಿ (ಬಿತ್ತನೆ + 30 ದಿನಗಳ ನಂತರ).',
    weatherInfoDetailed: 'ಈ ಮಾಡ್ಯೂಲ್‌ನಲ್ಲಿ ಎರಡು ಶಕ್ತಿಶಾಲಿ ವೈಶಿಷ್ಟ್ಯಗಳಿವೆ:\n\n🌍 ನೇರ ಹವಾಮಾನ: ನಿಮ್ಮ GPS ಸ್ಥಳ ಬಳಸಿ ನೈಜ-ಸಮಯ ಹವಾಮಾನ ತೋರಿಸುತ್ತದೆ.\n\n📊 ಅಪಾಯ ವಿಶ್ಲೇಷಣೆ: ಯಾವುದೇ ತಿಂಗಳು & ಉಷ್ಣತೆ ಆಯ್ಕೆ ಮಾಡಿ ಪ್ರವಾಹ, ಬರ ಅಂದಾಜು ಪಡೆಯಿರಿ.\n\n💡 ಸಲಹೆ: ಕೀಟನಾಶಕ ಸಿಂಪಡಿಸುವ ಮೊದಲು ಹವಾಮಾನ ಪರಿಶೀಲಿಸಿ.',
    soilInfoDetailed: 'ಈ ಸಾಧನ ಸಮಗ್ರ ಮಣ್ಣಿನ ಆರೋಗ್ಯ ವರದಿ ನೀಡುತ್ತದೆ:\n\n🟢 ಸಾರಜನಕ (N): ವ್ಯಾಪ್ತಿ 0-140 mg/kg.\n🟠 ರಂಜಕ (P): ವ್ಯಾಪ್ತಿ 0-140 mg/kg.\n🔵 ಪೊಟ್ಯಾಷಿಯಂ (K): ವ್ಯಾಪ್ತಿ 0-200 mg/kg.\n\n📊 ವರದಿಯಲ್ಲಿ: ಫಲವತ್ತತೆ ಅಂಕ, ಪೋಷಕ ವಿಶ್ಲೇಷಣೆ, ಗೊಬ್ಬರ ಶಿಫಾರಸುಗಳು\n\n💡 ಸಲಹೆ: ಸ್ಲೈಡರ್‌ಗಳಿಂದ ವಿವಿಧ N-P-K ಸಂಯೋಜನೆಗಳನ್ನು ಪ್ರಯತ್ನಿಸಿ.',
    cropInfoDetailed: 'ನಮ್ಮ AI 7 ಪ್ರಮುಖ ಅಂಶಗಳನ್ನು ವಿಶ್ಲೇಷಿಸುತ್ತದೆ:\n\n🧪 1. ಮಣ್ಣಿನ ಪೋಷಕಾಂಶಗಳು\n🔬 2. ಮಣ್ಣಿನ pH\n🌡️ 3. ಉಷ್ಣತೆ\n💧 4. ಆರ್ದ್ರತೆ\n🌧️ 5. ಮಳೆ\n\n📊 AI ಮಾಡೆಲ್ ಲಕ್ಷಗಟ್ಟಲೆ ಭಾರತೀಯ ಕೃಷಿ ಡೇಟಾದ ಮೇಲೆ ತರಬೇತಿ ಪಡೆದಿದೆ.\n\n💡 ಸಲಹೆ: ಸ್ವಲ್ಪ ಭಿನ್ನ ಮೌಲ್ಯಗಳನ್ನು ನಮೂದಿಸಿ ಪರ್ಯಾಯ ಬೆಳೆಗಳನ್ನು ಕಂಡುಹಿಡಿಯಿರಿ.',
