  'Apply Potash if low': 'applyPotashIfLow',
  'Based on your soil profile': 'basedOnProfile',
  '4-5 tons/hectare': 'tonsPerHectare45',
  '2-3 tons/hectare': 'tonsPerHectare23',
  'High Yield Potential': 'highYieldPotential',
  'Medium Yield Potential': 'mediumYieldPotential',
  'Low Yield Potential': 'lowYieldPotential',
  'Ensure proper drainage': 'ensureDrainage',
  'Avoid over-fertilization': 'avoidOverFertilization',
  'Monitor soil pH regularly': 'monitorPH',
  'Split fertilizer doses': 'splitDoses',
  'Maintain soil moisture': 'maintainMoisture',
  'Use organic mulch': 'organicMulch',
  'At sowing': 'atSowing',
  'Boost growth': 'boostGrowth',
  '6 months': 'sixMonths',
  'Estimated Yield': 'yieldLabel',
  'Yield Potential': 'yieldPotentialLabel',
